from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    result = []
    current_group = ""
    open_braces = 0

    for char in paren_string:
        if char == '(':
            open_braces += 1
        elif char == ')':
            open_braces -= 1

        current_group += char

        if open_braces == 0:
            result.append(current_group)  # Step 2 & 3: Separate groups and ensure balance
            current_group = ""

    return result  # Step 4: Return list of separate groups

